sys_script.script:
(function executeRule(current, previous) {

    var patientId = current.getValue('patient');
    var admissionId = current.getValue('admission');

    // Nothing to validate if Admission is empty.
    if (gs.nil(admissionId)) {
        return;
    }

    // Admission must have a patient.
    var admissionGR = new GlideRecord('x_2130921_caresy_0_admission');

    if (!admissionGR.get(admissionId)) {
        gs.addErrorMessage(
            'The selected Admission could not be found.'
        );

        current.setAbortAction(true);
        return;
    }

    var admissionPatientId = admissionGR.getValue('patient');

    // If a Patient is selected, it must match the Admission patient.
    if (!gs.nil(patientId) && patientId != admissionPatientId) {

        gs.addErrorMessage(
            'The selected Admission does not belong to the selected Patient.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
